package app;

import app.models.*;
import app.models.ini.ModelTypes;
import dal.api.DataBase;
import dal.api.DataBaseProcessor;
import net.WebUserContext;
import sprouts.Vars;
import swingtree.threading.EventProcessor;

import java.util.List;
import java.util.Optional;

/**
 *  Instances of this class are shared between all users as well as most view models in general.
 *  It is used to access persistent data and to perform operations on it.
 *  So here you can find access to the database, and all current user contexts, etc.
 *  <p>
 *  <b>Note that for every running application there is only one instance of this class.
 *  Please ensure that all methods are thread-safe and the implementation details are both
 *  well encapsulated and well documented.</b>
 */
public final class AppContext
{
    private final App app; // The application configuration
    private final DataBase db;
    private final ModelTypes modelTypes;

    private final Vars<UserContext> users = Vars.of(UserContext.class);



    public AppContext(App app) {
        this.app = app;
        this.db = DataBase.at(app.getDatabaseLocation()+"/"+app.getSaveFileName(), app.createQueryProcessor());
        this.modelTypes = new ModelTypes(db, app.getDatabaseLocation());
    }

    public ModelTypes modelTypes() { return modelTypes; }

    /**
     * Returns the application configuration which contains things like the database location, server port, etc.
     *
     * @return The application configuration.
     */
    public App app() { return app; }

    /**
     * Returns the database which is used to store persistent data, like users, characters, etc.
     *
     * @return The database API, which is from the TopSoil project.
     */
    public DataBase db() { return db; }

    public boolean userExists( String username ) {
        return db.select(User.class).where(User::username).is(username).exists();
    }

    public Optional<User> loginUser( String username ) {
        User user = db.select(User.class).where(User::username).is(username).first().orElse(null);
        if ( user != null ) {
            users.add(new UserContext(user));
            return Optional.of(user);
        }
        return Optional.empty();
    }

    public void registerWebUserContext(WebUserContext userContext) {
        // I don't know if the app context should care about web user contexts, I don't think so. For now.
    }

}

package dal.api;

import dal.impl.SQLiteDataBase;

import java.util.List;
import java.util.Objects;

/**
 *  This is the most important interface of the Topsoil ORM API which defines
 *  the database connection in terms of a thing that can create, delete and query
 *  extensions of the {@link Model} interface.
 *  The {@link DataBase} will implement your model interfaces for you through proxies
 *  which will eagerly translate the interactions with your model objects
 *  into SQL queries and updates. All the complicated SQL code is generated
 *  at run time by the internal {@link SQLiteDataBase} class,
 *  you don't have to think about it.
 *  This type of ORM is especially useful for Swing applications or other
 *  desktop applications where many small database operations are not a problem. <br>
 *  You simply create a {@link DataBase} instance by calling the static method like so:
 *  <pre>{@code
 *      DataBase db = DataBase.at("path/to/my/my.db");
 *  }</pre>
 *  The {@link DataBase} will then create a connection to the underlying SQLite database
 *  and will create a database file if it does not exist already, this is where all the
 *  data will be stored. <br>
 *  Before creating model instances you have to register them with the {@link DataBase}
 *  so that it can create the tables for them.
 *  If your models have relations to other models you have to register the involved model types all
 *  at once by passing them to the {@link DataBase#createTablesFor(Class[])}
 *  method. <br>
 *  You can then create a model by calling the {@link DataBase#create(Class)} method.<br>
 *  Here is an example of how to do this:
 *  <pre>{@code
 *    DataBase db = DataBase.at("path/to/my/my.db");
 *    // Register the model
 *    db.createTablesFor(MyModel.class, MyOtherModel.class);
 *    // Create a model instance
 *    MyModel model = db.create(MyModel.class);
 *    // Do something with the model
 *    System.out.println(model.id().get());
 *    model.someProperty().set("Hello World!");
 *    // The model will be persisted automatically!
 *  } </pre>
 *  You can also query the database by using the {@link DataBase#select(Class)} method
 *  like so: <br>
 *  <pre>{@code
 *    DataBase db = DataBase.at("path/to/my/my.db");
 *    // ... some code to register and create many models ...
 *    // Query the database:
 *    List<MyModel> models = db.select(MyModel.class)
 *                                .where(MyModel::someProperty).is("Hello World!")
 *                                .asList();
 * }</pre>
 */
public interface DataBase
{
    /**
     * Creates a new {@link DataBase} instance representing a database at
     * the specified path.
     * If a database already exists at the specified path it will be opened,
     * otherwise a new database file will be created.
     *
     * @param path The path to the database file.
     * @return A new {@link DataBase} instance.
     */
    static DataBase at( String path ) {
        var mainThread = Thread.currentThread();
        return at(path, new DataBaseProcessor() {
            @Override public void process(Runnable task) { task.run(); }
            @Override public void processNow(Runnable task) { task.run(); }
            @Override public List<Thread> getThreads() { return List.of(mainThread); }
        });
    }

    /**
     * Creates a new {@link DataBase} instance representing a database at
     * the specified path, together with a custom {@link DataBaseProcessor},
     * which is used to process database operations.
     * If a database already exists at the specified path it will be opened,
     * otherwise a new database file will be created.
     *
     * @param path The path to the database file.
     * @param processor The processor to use for processing database operations.
     * @return A new {@link DataBase} instance.
     */
    static DataBase at( String path, DataBaseProcessor processor ) {
        Objects.requireNonNull(path);
        return new SQLiteDataBase(path, processor);
    }

    /**
     *  Creates tables for the specified model types.
     *  If a table for a model type already exists it will not be overwritten.
     *
     * @param models The model types to create tables for.
     */
    void createTablesFor( Class<? extends DataBaseEntity>... models );

    /**
     *  Drops all tables corresponding to the provided model types.
     *
     * @param models The model types to drop tables for.
     */
    void dropTablesFor( Class<? extends DataBaseEntity>... models );

    /**
     * @return A list of the names of all tables in the database.
     */
    List<String> listOfAllTableNames();

    /**
     * @param sql The SQL code to execute.
     */
    void execute( String sql );

    /**
     *  Drops all tables in the database.
     */
    void dropAllTables();

    /**
     *  Drops the table corresponding to the provided model type.
     *
     * @param model The model type to drop the table for.
     */
    void dropTable( Class<? extends DataBaseEntity> model );

    /**
     *  This method is useful for debugging purposes as it unveils the SQL code
     *  that backs the supplied model type.<br>
     *  Note that this only works if a table for the model type has been created
     *  through the {@link DataBase#createTablesFor(Class[])} method.
     *
     *  @param model The model type to get the table SQL code for.
     *  @return The SQL code of the table corresponding to the provided model type.
     */
    String sqlCodeOfTable( Class<? extends DataBaseEntity> model );

    /**
     *  Creates and returns a new instance of the specified {@link Model} type.<br>
     *  The returned model instance is an eager representation of a database record.
     *
     * @param model The type of the model to create and return.
     * @param <M> The type of the model.
     * @return A new instance of the specified model type.
     */
    <M extends Model<M>> M create( Class<M> model );

    /**
     *  Selects a single {@link Model} instance from the database by its id.<br>
     *
     * @param model The type of the model to select and return as that type.
     * @param id The id of the model to select.
     * @param <T> The generic type of the model, to ensure type safety.
     * @return The model with the specified id or null if no such model exists.
     */
    <T extends Model<T>> T select( Class<T> model, long id );

    /**
     *  Selects all the {@link Model}s of the specified type from the database.<br>
     *  This is equivalent to:
     *  <pre>{@code
     *      db.select(User.class).asList();
     *  }</pre>
     *
     * @param models The type of the models to select.
     * @param <M> The type of the models.
     * @return A list of all the models of the specified type.
     */
    <M extends Model<M>> List<M> selectAll( Class<M> models );

    /**
     *  Deletes the supplied {@link Model} from the database.
     *
     * @param model The model to delete.
     * @param <M> The type of the model.
     */
    <M extends Model<M>> void delete( M model );

    /**
     *  Deletes all the {@link Model}s in the supplied list.
     *
     * @param models The models to delete.
     * @param <M> The type of the models.
     */
    default <M extends Model<M>> void delete( List<M> models ) {
        models.forEach(this::delete);
    }

    /**
     *  Deletes all the {@link Model}s in the supplied query.<br>
     *  In practice, this may look like this:
     *  <pre>{@code
     *      db.delete(
     *          db.select(User.class)
     *          .where(User::age)
     *          .greaterThan(42)
     *      );
     *      // Deletes all users with an age greater than 42.
     *  }</pre>
     *
     * @param modelQuery The query to delete models from.
     * @param <M> The type of the models.
     */
    default <M extends Model<M>> void delete( Query<M> modelQuery ) {
        modelQuery.asList().forEach(this::delete);
    }

    /**
     *  Exposes a fluent builder API in the form of the {@link Query} interface.
     *  Use this to query the database similar to SQL.
     *  Here is an example:
     *  <pre>{@code
     *    List<User> users = db.select(User.class)
     *                          .where(User::name).is("John")
     *                          .and(User::age).greaterThan(18)
     *                          .asList();
     * }</pre>
     * @param model The model type class used to find the table in the database.
     * @return A {@link Query} object which exposes a fluent builder API.
     * @param <M> The type of the {@link Model} to query.
     */
    <M extends Model<M>> Where<M> select( Class<M> model );

    /**
     *  Closes the native database connection.<br>
     *  This will effectively close the database and all its resources
     *  and will make the database instance unusable after this method is called.
     */
    void close();

}

package dal.api;

import java.util.List;
import java.util.Optional;
import java.util.Set;

/**
 *  The last step in the fluent query builder API of the {@link DataBase}
 *  which defines in what form the result of the query should be returned.
 *  Usually the result is a simple list of models, but there are also alternative
 *  methods, which are very useful.
 *  For example, if the query is supposed to return exactly a single item, the
 *  {@link #expectOne()} method should be used, on the other hand if the query
 *  is supposed to return one or no items, the {@link #expectOneOrNone()} method.
 *
 * @param <M> The type of the model to query.
 */
public interface Query<M extends Model<M>>
{
    /**
     *  Returns the result of the query as a list of models.
     *  If the query is supposed to return multiple items you may also use the
     *  {@link #asSet()} method.
     *
     * @return The result of the query as a list of models.
     */
    List<M> asList();

    /**
     *  Returns the result of the query as a set of models.
     *  If the query is supposed to return multiple items you may also use the
     *  {@link #asList()} method.
     *
     * @return The result of the query as a set of models.
     */
    default Set<M> asSet() { return Set.copyOf(asList()); }

    /**
     *  Returns the result of the query as a single model or throws an exception
     *  if the query result is empty or contains more than one item.
     *
     * @return The result of the query as a single model.
     */
    default M expectOne() {
        List<M> list = asList();
        if ( list.size() != 1 )
            throw new IllegalStateException("Expected exactly one result, but got " + list.size());

        return list.get(0);
    }

    /**
     *  Returns the result of the query as a single model or throws an exception
     *  if the query result contains more than one item.
     *  If the query result is empty, an empty {@link Optional} is returned.
     *
     * @return The result of the query as a single model wrapped in an {@link Optional}, which
     *        is empty if the query result is empty.
     */
    default Optional<M> expectOneOrNone() {
        List<M> list = asList();
        if ( list.size() > 1 )
            throw new IllegalStateException("Expected at most one result, but got " + list.size());

        return list.isEmpty() ? Optional.empty() : Optional.of(list.get(0));
    }

    /**
     *  Returns the first item of the query result or if the
     *  query result is empty, an empty {@link Optional} is returned.
     *
     * @return The first item of the query result wrapped in an {@link Optional}, which
     *         is empty if the query result is empty.
     */
    default Optional<M> first() { return asList().stream().findFirst(); }

    /**
     *  Returns the last item of the query result or if the
     *  query result is empty, an empty {@link Optional} is returned.
     *
     * @return The last item of the query result wrapped in an {@link Optional}, which
     *         is empty if the query result is empty.
     */
    default Optional<M> last() { return asList().stream().reduce((first, second) -> second); }

    default List<M> limit(int limit) { return asList().subList(0, limit); }

    default List<M> skip(int skip) { return asList().subList(skip, asList().size()); }

    default List<M> skip(int skip, int limit) { return asList().subList(skip, skip + limit); }

    default int count() { return asList().size(); }

    default boolean exists() { return !asList().isEmpty(); }

    default boolean notExists() { return asList().isEmpty(); }
}

package dal.api;

import sprouts.Val;

import java.util.List;

/**
 *   A step in the fluent query builder API of the {@link DataBase}
 *   which defines the comparison of a previously defined field with a value.
 *
 * @param <M> The type of the model to query.
 * @param <T> The type of the field to compare.
 */
public interface Compare<M extends Model<M>, T>
{
    /**
     *  Checks if the selected field is equal to the given value.
     *
     * @param value The value to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> is( T value );

    /**
     * Checks if the selected field is equal to the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> is( Val<T> value ) { return is(value.get()); }

    /**
     *  Checks if the selected field is not equal to the given value.
     *
     * @param value The value to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> isNot( T value );

    /**
     * Checks if the selected field is not equal to the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> isNot( Val<T> value ) { return isNot(value.get()); }

    /**
     *  Checks if the selected field is like the given value.
     *  Like means that the given value is expected to be a string pattern which may contain
     *  the wildcard character '%' which matches any sequence of characters.
     *
     * @param value The value to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> like( T value );

    /**
     * Checks if the selected field is like the value of the given property.
     * Like means that the given value is a pattern which may contain
     * the wildcard character '%' which matches any sequence of characters.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> like( Val<T> value ) { return like(value.get()); }

    /**
     *  Checks if the selected field is not like the given value.
     *  Like means that the given value is expected to be a string pattern which may contain
     *  the wildcard character '%' which matches any sequence of characters.
     *
     * @param value The value to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> notLike( T value );

    /**
     * Checks if the selected field is not like the value of the given property.
     * Like means that the given value is a pattern which may contain
     * the wildcard character '%' which matches any sequence of characters.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> notLike( Val<T> value ) { return notLike(value.get()); }

    /**
     *  Checks if the selected field is within the provided array of arguments.
     *
     * @param values The values to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> in( T... values );

    /**
     * Checks if the selected field is within the provided array of property arguments.
     * @param values The properties whose items should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> in( Val<T>... values ) {
        T[] vals = (T[]) new Object[values.length];
        for (int i = 0; i < values.length; i++) {
            vals[i] = values[i].get();
        }
        return in(vals);
    }

    /**
     * Checks if the value of the selected field is within the provided list.
     * @param values The list of values to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> in( List<T> values ) {
        return in(values.toArray((T[]) new Object[values.size()]));
    }

    /**
     *  Checks if the selected field is NOT within the provided array of arguments.
     *
     * @param values The values to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> notIn(T... values);

    /**
     * Checks if the values of the selected field are NOT within the provided array of property arguments.
     * @param values The properties whose items should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> notIn( Val<T>... values ) {
        T[] vals = (T[]) new Object[values.length];
        for ( int i = 0; i < values.length; i++ ) {
            vals[i] = values[i].get();
        }
        return notIn(vals);
    }

    /**
     * Checks if the values of the selected field is NOT within the provided list.
     * @param values The list of values to compare the selected field with.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> notIn( List<T> values ) {
        return notIn(values.toArray((T[]) new Object[values.size()]));
    }

    /**
     *  Checks if the values of the selected field are null.
     *
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> isNull();

    /**
     *  Checks if the values of the selected field are not null.
     *
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> isNotNull();

    /**
     *  Checks if the values of the selected field are greater than the given value.
     *
     *  @param value The value to compare the selected field with.
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> greaterThan( T value );

    /**
     * Checks if the values of the selected field are greater than the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> greaterThan( Val<T> value ) { return greaterThan(value.get()); }

    /**
     *  Checks if the values of the selected field are greater than or equal to the given value.
     *
     *  @param value The value to compare the selected field with.
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> greaterThanOrEqual( T value );

    /**
     * Checks if the values of the selected field are greater than or equal to the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> greaterThanOrEqual( Val<T> value ) { return greaterThanOrEqual(value.get()); }

    /**
     *  Checks if the values of the selected field are less than the given value.
     *
     *  @param value The value to compare the selected field with.
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> lessThan( T value );

    /**
     * Checks if the values of the selected field are less than the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> lessThan( Val<T> value ) { return lessThan(value.get()); }

    /**
     *  Checks if the values of the selected field are less than or equal to the given value.
     *
     *  @param value The value to compare the selected field with.
     *  @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    Junction<M> lessThanOrEqual( T value );

    /**
     * Checks if the values of the selected field are less than or equal to the value of the given property.
     * @param value The property whose item should be compared with the selected field.
     * @return A {@link Junction} object which allows to define a chain of boolean operations
     */
    default Junction<M> lessThanOrEqual( Val<T> value ) { return lessThanOrEqual(value.get()); }

}

