1	package dal.impl;
2	
3	import dal.api.DataBaseEntity;
4	import dal.api.Model;
5	import dal.api.Value;
6	import org.jspecify.annotations.NullMarked;
7	import org.jspecify.annotations.Nullable;
8	import sprouts.*;
9	
10	import java.lang.invoke.MethodHandles;
11	import java.lang.invoke.MethodType;
12	import java.lang.reflect.*;
13	import java.util.Objects;
14	import java.util.Optional;
15	
16	@NullMarked
17	record EntityTableField(
18	    String baseName, // The method baseName from the model class
19	    Class<? extends DataBaseEntity> ownerModelClass, // The model class
20	    FieldType type,
21	    boolean allowNull
22	) {
23	    sealed interface Params {
24	        Class<?> type();
25	        record Single(Class<?> type) implements Params {}
26	        record TupleOf(Class<?> type) implements Params {}
27	    }
28	
29	    public static EntityTableField ofValue(
30	            final Method method, // The method from the model class
31	            final Class<? extends Value> ownerEntityClass, // The model class
32	            final Tuple<Class<? extends DataBaseEntity>> otherEntities
33	    ) {
34	        final String methodName = method.getName();
35	        final Class<?> methodReturnType = method.getReturnType(); // The type of the property and return type of the method
36	        final Type declaredReturnTypeGenericParam = method.getGenericReturnType();
37	        boolean isTuple = Tuple.class.isAssignableFrom(methodReturnType);
38	        boolean isPrimitive = BasicSQLiteDataBase._isBasicDataType(methodReturnType);
39	        boolean isValue = Value.class.isAssignableFrom(methodReturnType);
40	        if ( Value.class.isAssignableFrom(ownerEntityClass) ) {
41	            if ( !isTuple && !isPrimitive && !isValue ) {
42	                throw new IllegalArgumentException(
43	                        "The return type of " + methodName + "() must be a tuple, primitive or Value"
44	                );
45	            }
46	        }
47	        var params = extractParamsFrom(declaredReturnTypeGenericParam, methodName);
48	        FieldKind kind;
49	        if ( isTuple )
50	            kind = FieldKind.INTERMEDIATE_TABLE;
51	        else if ( isPrimitive )
52	            kind = FieldKind.PRIMITIVE;
53	        else
54	            kind = FieldKind.FOREIGN_KEY;
55	        FieldType fieldType = null;
56	        if ( isTuple )
57	            fieldType = new FieldType.Tuple((Class)params.type());
58	        if ( isPrimitive )
59	            fieldType = new FieldType.Primitive(params.type());
60	        if ( isValue )
61	            fieldType = new FieldType.Value((Class)params.type());
62	        return new EntityTableField(
63	                methodName,
64	                ownerEntityClass,
65	                Objects.requireNonNull(fieldType),
66	                false
67	        );
68	    }
69	
70	    public static EntityTableField of(
71	        final Method method, // The method from the model class
72	        final Class<? extends DataBaseEntity> ownerEntityClass, // The model class
73	        final Tuple<Class<? extends DataBaseEntity>> otherEntities
74	    ) {
75	        final String methodName = method.getName();
76	        final Class<?> methodReturnType = method.getReturnType(); // The type of the property and return type of the method
77	        final Type declaredReturnTypeGenericParam = method.getGenericReturnType();
78	        Params propertyParams = null; // The type of the property value
79	        FieldKind kind;
80	        boolean itemIsModel;
81	
82	        // First we check if the return type is a subclass of Val or Vals
83	        boolean isSubTypeOfVal  = Val.class.isAssignableFrom(methodReturnType);
84	        boolean isSubTypeOfVals = Vals.class.isAssignableFrom(methodReturnType);
85	        boolean isValOrVar   = methodReturnType == Val.class  || methodReturnType == Var.class;
86	        boolean isValsOrVars = methodReturnType == Vals.class || methodReturnType == Vars.class;
87	
88	        if ( Model.class.isAssignableFrom(ownerEntityClass) ) {
89	            if ( !isSubTypeOfVal && !isSubTypeOfVals )
90	                throw new IllegalArgumentException(
91	                        "The return type of method '" + methodName + "' " +
92	                        "in model type '" + ownerEntityClass.getName() + "' " +
93	                        "is not a subclass of " +
94	                        "either " + Val.class.getName() + " or " + Vals.class.getName() + ". \n" +
95	                        "You might want to declare the method as a default method in the model interface " +
96	                        "or wrap the return type in a property type, like so: \n" +
97	                        "'public " + Var.class.getSimpleName() + "<" + methodReturnType.getSimpleName() + "> " + methodName + "()'"
98	                    );
99	        } else if ( Value.class.isAssignableFrom(ownerEntityClass) ) {
100	            throw new IllegalStateException("Unexpected factory method argument.");
101	        }
102	
103	        // Great that is correct! But now we have another requirement:
104	        /*
105	            So a model interface might look something like this:
106	            public interface Person extends Model<Person> {
107	                interface Name extends Var<String> {} // Val is a property type with getter and setter
108	                interface Addresses extends Vars<Address> {} // Vars is a property type with getter and setter wrapping multiple values
109	                Name name();
110	                Var<Integer> age(); // Not declared as an inner interface of the model interface, which is okay
111	            }
112	            We expect that the return type of the method is either equal to or a subclass of Val/Vals...
113	            ...if it is a subclass we also expect it to be declared as an inner interface of the model interface!
114	            This is because of readability and coherence and also
115	            because we might need to be able to get the name of the field from the interface in the query API!
116	
117	            The main goal here is to get the type of the value of the property
118	            This is a generic type parameter of the Val interface
119	            So in the example below for "Name" it would be String
120	            and for method "age" it would be Integer:
121	
122	            public interface Person extends Model<Person> {
123	                interface Name extends Val<String> {} // Val is a property type with getter and setter
124	                Name name();
125	                Var<Integer> age(); // Not declared as an inner interface of the model interface, which is okay
126	            }
127	         */
128	        if ( !isValOrVar && !isValsOrVars ) {
129	            // It is a subclass of Val or Vals:
130	            TypeVariable<?>[] typeParameters = methodReturnType.getTypeParameters();
131	            if (typeParameters.length != 0)
132	                throw new IllegalArgumentException(
133	                        "The return type of the method " + methodName + " may not have generic parameters!"
134	                );
135	            Type[] genericInterfaces = methodReturnType.getGenericInterfaces();
136	            if (genericInterfaces.length != 1)
137	                throw new IllegalArgumentException(
138	                        "The return type of the method " + methodName + " must implement exactly one interface!"
139	                );
140	
141	            Type genericInterface = genericInterfaces[0];
142	            Type[] actualTypeArguments = ((ParameterizedType) genericInterface).getActualTypeArguments();
143	            propertyParams = extractParamsFrom(actualTypeArguments[0], methodName);
144	        } else {
145	            // The return type is Val<T>, Var<T>, Vals<T> or Vars<T> so we can get the type parameter T easily:
146	            // However we can not get the declared type from Var,Val... it is a generic type...
147	            // Instead, we get the type from the method parameter
148	            propertyParams = extractParamsFrom(declaredReturnTypeGenericParam, methodName);
149	        }
150	        // Now we need to determine the kind of the field, here are the possibilities:
151	        /*
152	            public interface Person extends Model<Person> {
153	                interface Address extends Var<Address> {}  // Kind: FOREIGN_KEY
154	                interface Name extends Var<String> {}      // Kind: PRIMITIVE
155	                interface Age extends Var<Integer> {}      // Kind: PRIMITIVE
156	                interface Children extends Vars<Person> {} // Kind: INTERMEDIATE_TABLE
157	            }
158	            // ... and ...
159	            public interface Model<M> {
160	                interface Id extends Val<Integer> {} // Kind: ID
161	                Id id();
162	                ...
163	            }
164	         */
165	
166	        // First, we check if the field is an ID field
167	        if (methodName.equals(EntityTable.ID)) {
168	            if (!methodReturnType.equals(Model.Id.class))
169	                throw new IllegalArgumentException(
170	                    "The return type of the method " + methodName + " is not " + Model.Id.class.getName()
171	                );
172	            kind = FieldKind.ID;
173	        }
174	        // Then we check if the field is a foreign key field
175	        else if ( isSubTypeOfVal ) {
176	            if ( propertyParams instanceof Params.TupleOf && Value.class.isAssignableFrom(propertyParams.type()) ) {
177	                if (otherEntities.contains((Class<? extends Value>) propertyParams.type())) {
178	                    kind = FieldKind.INTERMEDIATE_TABLE;
179	                } else {
180	                    if (BasicSQLiteDataBase._isBasicDataType(propertyParams.type()))
181	                        throw new IllegalArgumentException(
182	                                "List of basic data types cannot be modelled as table fields."
183	                        );
184	                    else
185	                        throw new IllegalArgumentException(
186	                            "Cannot establish table field for method '" + methodName + "()' for value type '" + ownerEntityClass.getName() + "', \n" +
187	                            "because the return type of the method is a property referencing a tuple of values " +
188	                            "with type '" + propertyParams.type().getName() + "', which is however not known " +
189	                            "by the database, please make sure that it is passed to the 'createTablesFor(..)' method alongside " +
190	                            "all other value and model types!"
191	                        );
192	                }
193	            } else if (Value.class.isAssignableFrom(propertyParams.type())) {
194	                if (otherEntities.contains((Class<? extends Value>) propertyParams.type())) {
195	                    kind = FieldKind.FOREIGN_KEY;
196	                } else
197	                    throw new IllegalArgumentException(
198	                        "Cannot establish table field for method '" + methodName + "()' for value type '" + ownerEntityClass.getName() + "', \n" +
199	                        "because the return type of the method is a property referencing another value " +
200	                        "called '" + propertyParams.type().getName() + "', which is however not known " +
201	                        "by the database, please make sure that it is passed to the 'createTablesFor(..)' method alongside " +
202	                        "all other value and model types!"
203	                    );
204	            } else if (Model.class.isAssignableFrom(propertyParams.type())) {
205	                if (otherEntities.contains((Class<? extends Model<?>>) propertyParams.type())) {
206	                    kind = FieldKind.FOREIGN_KEY;
207	                } else
208	                    throw new IllegalArgumentException(
209	                        "Cannot establish table field for method '" + methodName + "()' for model '" + ownerEntityClass.getName() + "', \n" +
210	                        "because the return type of " +
211	                        "the method is a property referencing another model called '" + propertyParams.type().getName() + "', " +
212	                        "which is however not known " +
213	                        "by the database, please make sure that it is passed to the 'createTablesFor(..)' method alongside " +
214	                        "all other model types!"
215	                    );
216	            } else if (BasicSQLiteDataBase._isBasicDataType(propertyParams.type())) {
217	                kind = FieldKind.PRIMITIVE;
218	            } else {
219	                boolean propertyValueIsModel = Model.class.isAssignableFrom(propertyParams.type());
220	                if ( !propertyValueIsModel )
221	                    throw new IllegalArgumentException(
222	                            "Failed to create table field '" + methodName + "' for model '" + ownerEntityClass.getName() + "', because \n" +
223	                            "the property value type '" + propertyParams.type().getName() + "' in declared method " +
224	                            "'public " + methodReturnType.getSimpleName() + "<" + propertyParams.type().getSimpleName() + "> " + methodName + "();' " +
225	                            "is not a basic data type and is also not recognisable as another model! \n" +
226	                            "If you want this declaration to work, make sure that '" + propertyParams.type().getName() + "' is a subtype of the '" + Model.class.getName() + "' interface " +
227	                            "and also is passed to the the 'createTablesFor(Class<M>... models);' method."
228	                        );
229	                else // The user has simply not passed the interface class to the createTablesFor(Class<Model... models) method:
230	                    throw new IllegalArgumentException(
231	                            "Failed to create table field '" + methodName + "' for model '" + ownerEntityClass.getName() + "', because \n" +
232	                            "the property value type '" + propertyParams.type().getName() + "' in declared method " +
233	                            "'public " + methodReturnType.getSimpleName() + "<" + propertyParams.type().getSimpleName() + "> " + methodName + "();' " +
234	                            "is a model type not known to the database! " +
235	                            "If you want this declaration to work, make sure that you have passed the interface class of the model to the " +
236	                            "createTablesFor(Class<M>... models); method!"
237	                        );
238	            }
239	        }
240	        // Then we check if the field is an intermediate table field
241	        else if (isSubTypeOfVals) {
242	            if (otherEntities.contains((Class<? extends Model<?>>) propertyParams.type())) {
243	                kind = FieldKind.INTERMEDIATE_TABLE;
244	            } else {
245	                if (BasicSQLiteDataBase._isBasicDataType(propertyParams.type()))
246	                    throw new IllegalArgumentException(
247	                            "List of basic data types cannot be modelled as table fields."
248	                    );
249	                else
250	                    throw new IllegalArgumentException(
251	                            "The type '" + methodReturnType.getName() + "' of the property returned by " +
252	                                    "method " + methodName + " is not a known model type."
253	                    );
254	            }
255	        } else
256	            throw new IllegalArgumentException(
257	                    "The return type of the method " + methodName + " is not a subclass " +
258	                            "of " + Val.class.getName() + " or " + Vals.class.getName() + " with one type parameter"
259	            );
260	
261	        itemIsModel = Model.class.isAssignableFrom(propertyParams.type());
262	        var itemIsValue = Value.class.isAssignableFrom(propertyParams.type());
263	        FieldType fieldType = null;
264	        if ( isSubTypeOfVal ) {
265	            if ( kind == FieldKind.ID )
266	                fieldType = new FieldType.VarOf.Id((Class) methodReturnType, propertyParams.type());
267	            if ( itemIsModel )
268	                fieldType = new FieldType.VarOf.Model((Class) methodReturnType, (Class) propertyParams.type());
269	            if ( kind == FieldKind.PRIMITIVE )
270	                fieldType = new FieldType.VarOf.Primitive((Class) methodReturnType, propertyParams.type());
271	            if ( itemIsValue ) {
272	                if ( kind == FieldKind.INTERMEDIATE_TABLE )
273	                    fieldType = new FieldType.VarOf.Tuple((Class) methodReturnType, (Class) propertyParams.type());
274	                else
275	                    fieldType = new FieldType.VarOf.Value((Class) methodReturnType, (Class) propertyParams.type());
276	            } else if ( kind == FieldKind.INTERMEDIATE_TABLE ) {
277	                fieldType = new FieldType.VarOf.Model((Class) methodReturnType, (Class) propertyParams.type());
278	            }
279	        }
280	        if ( isSubTypeOfVals ) {
281	            if ( itemIsModel )
282	                fieldType = new FieldType.VarsOf.Model((Class) methodReturnType, (Class) propertyParams.type());
283	            if ( kind == FieldKind.PRIMITIVE )
284	                fieldType = new FieldType.VarsOf.Primitive((Class) methodReturnType, propertyParams.type());
285	            if ( itemIsValue )
286	                fieldType = new FieldType.VarsOf.Value((Class) methodReturnType, (Class)propertyParams.type());
287	            if ( kind == FieldKind.INTERMEDIATE_TABLE ) {
288	                fieldType = new FieldType.VarsOf.Model((Class) methodReturnType, (Class) propertyParams.type());
289	            }
290	        }
291	        return new EntityTableField(
292	                methodName,
293	                ownerEntityClass,
294	                Objects.requireNonNull(fieldType),
295	                itemIsModel
296	            );
297	    }
298	
299	    private static Params extractParamsFrom(Type type, String methodName) {
300	        if ( type instanceof ParameterizedType ) {
301	            if ( !Tuple.class.equals(((ParameterizedType) type).getRawType()) ) {
302	                var declaredReturnTypeGenericParamType = ((ParameterizedType) type).getActualTypeArguments()[0];
303	                if ( declaredReturnTypeGenericParamType instanceof Class<?> ) {
304	                    return new Params.Single((Class<?>) declaredReturnTypeGenericParamType);
305	                } else {
306	                    throw new IllegalArgumentException(
307	                      "The type arguments of return type of the method " + methodName + " must be a class!"
308	                    );
309	                }
310	            }
311	            /*
312	               We have a tuple of things as value, which
313	               would like this:
314	
315	               public interface School extends Model<School> {
316	                   interface Students extends Var<Tuple<Person>> {}
317	                   interface Teachers extends Var<Tuple<Person>> {}
318	               }
319	
320	               So we need to get the parameter type of the tuple.
321	               Which in the above example would be: Person.class
322	            */
323	            var actualTypeArguments = ((ParameterizedType)type).getActualTypeArguments();
324	            if ( actualTypeArguments == null || actualTypeArguments.length != 1 ) {
325	                throw new IllegalArgumentException(
326	                    "Invalid declaration of method '"+methodName+"'!  " +
327	                    "Expected a single parameterized type, but found: "+type
328	                );
329	            } else {
330	                var paramType = actualTypeArguments[0];
331	                if ( paramType instanceof Class<?> ) {
332	                    return new Params.TupleOf((Class<?>) paramType);
333	                } else {
334	                    throw new IllegalArgumentException(
335	                        "Invalid declaration of method  '"+methodName+"'!   "+
336	                        "Expected a single parameterized type, but found:  "+paramType
337	                    );
338	                }
339	            }
340	        } else if ( type instanceof Class ) {
341	            return new Params.Single((Class<?>) type);
342	        } else {
343	            throw new IllegalArgumentException(
344	                "Invalid declaration of method '"+methodName+"'! " +
345	                "Property parameter type of method return type not recognizable!"
346	            );
347	        }
348	    }
349	
350	    public String name() {
351	        if ( type().kind() == FieldKind.FOREIGN_KEY )
352	            return EntityTable.FK_PREFIX + baseName() + EntityTable.FK_POSTFIX;
353	        return baseName();
354	    }
355	
356	    public boolean isField(String name) {
357	        return baseName().equals(name);
358	    }
359	
360	    public boolean isList() {
361	        var wrapperType = type().wrapperType();
362	        if ( wrapperType == null )
363	            return false;
364	        return Vals.class.isAssignableFrom(wrapperType);
365	    }
366	
367	    public boolean isTuple() {
368	        var wrapperType = type().wrapperType();
369	        if ( wrapperType == null )
370	            return false;
371	        // TODO: This only works for 'Tuple<T>' fields, but not 'Var<Tuple<T>>' fields.
372	        return Tuple.class.isAssignableFrom(wrapperType);
373	    }
374	
375	    public FieldKind getKind() {
376	        return type().kind();
377	    }
378	
379	    public boolean requiresIntermediateTable() {
380	        return type().kind() == FieldKind.INTERMEDIATE_TABLE;
381	    }
382	
383	    public boolean isForeignKey() {
384	        return type().kind() == FieldKind.FOREIGN_KEY;
385	    }
386	
387	    public String toTableFieldStatement() {
388	        return name() + " " + BasicSQLiteDataBase._fromJavaTypeToDBType(type().item());
389	    }
390	
391	    public Optional<IntermediateTable> getIntermediateTable() {
392	        if (requiresIntermediateTable())
393	            return Optional.of(new IntermediateTable(this));
394	        else
395	            return Optional.empty();
396	    }
397	
398	    public ProxyRef<Val<Object>> asProperty(SQLiteDataBase db, long id, boolean eager ) {
399	        var wrapperType = type().wrapperType();
400	        var itemType = type().item();
401	        if ( wrapperType == null )
402	            throw new IllegalStateException(
403	                            "Cannot create a property proxy for a field that does not have a wrapper type."
404	                        );
405	
406	        var prop = new ModelProperty(
407	                        db, id, this.name(),
408	                        BasicSQLiteDataBase._tableNameFromClass(ownerModelClass),
409	                        (FieldType.VarOf) this.type,
410	                        allowNull,
411	                        eager
412	                    );
413	
414	        // Let's check if the property is a Val
415	        boolean isVal = Val.class.isAssignableFrom(wrapperType);
416	        if (!isVal)
417	            throw new IllegalArgumentException(
418	                    "The return type of the method " + baseName() + " is not a subclass " +
419	                            "of " + Val.class.getName() + " or " + Vals.class.getName() + " with one type parameter"
420	            );
421	
422	        // Let's create the proxy:
423	        return new ProxyRef<>((Val<Object>) Proxy.newProxyInstance(
424	                        wrapperType.getClassLoader(),
425	                        new Class[]{wrapperType, Viewable.class},
426	                        (proxy, method, args) -> {
427	                            return _handleInvocation(proxy, method, args, prop, wrapperType);
428	                        }
429	                    ),
430	                    prop
431	                );
432	    }
433	
434	    private Object _handleInvocation(
435	        Object proxy,
436	        Method method,
437	        Object[] args,
438	        Object prop,
439	        Class<?> propertyType
440	    ) throws InvocationTargetException, IllegalAccessException {
441	        String methodName = method.getName();
442	        // Check if it is 'toString()':
443	        if ( methodName.equals("toString") && (args == null || args.length == 0) ) {
444	            return prop.toString();
445	        }
446	        try {
447	            Method proxyTypeMethod = propertyType.getMethod(methodName, method.getParameterTypes());
448	            // Then we expect the method to be a default method
449	            if (proxyTypeMethod.isDefault()) {
450	                // A default method is a method that is defined in an interface, we can just call it
451	                return MethodHandles.lookup()
452	                        .findSpecial(
453	                                propertyType,
454	                                methodName,
455	                                MethodType.methodType(method.getReturnType(), method.getParameterTypes()),
456	                                propertyType
457	                        )
458	                        .bindTo(proxy)
459	                        .invokeWithArguments(args);
460	            }
461	        } catch (Exception e) {
462	            // If we get here, it means that the method is not a default method
463	        } catch (Throwable e) {
464	            throw new RuntimeException(e);
465	        }
466	        try {
467	            // Here we delegate to the property
468	            return method.invoke(prop, args);
469	            /*
470	                The method here might be one of the following:
471	                - get()
472	                - orElseNull()
473	                - set(T value)
474	                - isEmpty()
475	                - ... see Val & Var interfaces for more ...
476	            */
477	        } catch (InvocationTargetException e) {
478	            // We don't really care about the InvocationTargetException, we just want to throw the cause exception:
479	            if (e.getCause() instanceof RuntimeException)
480	                throw (RuntimeException) e.getCause();
481	            else
482	                throw new RuntimeException(e.getCause());
483	        }
484	    }
485	
486	    public Optional<String> asSqlColumn() {
487	        var itemType = type.item();
488	        var kind = type.kind();
489	        String name = name();
490	        if (!DataBaseEntity.class.isAssignableFrom(itemType)) {
491	            String properties = allowNull ? "" : " NOT NULL";
492	            if (name.equals(EntityTable.ID))
493	                properties += " PRIMARY KEY AUTOINCREMENT";
494	            return Optional.of(name + " " + BasicSQLiteDataBase._fromJavaTypeToDBType(itemType) + properties);
495	        } else if ( kind == FieldKind.FOREIGN_KEY) {
496	            String otherTable = BasicSQLiteDataBase._tableNameFromClass(itemType);
497	            return Optional.of(name + " INTEGER REFERENCES " + otherTable + "("+ EntityTable.ID+")");
498	        } else if ( kind == FieldKind.INTERMEDIATE_TABLE) {
499	            return Optional.empty(); // The field is not a column in the table, but a table itself
500	        } else
501	            throw new IllegalStateException("Unknown field kind: " + kind);
502	    }
503	
504	    public @Nullable Object getDefaultValue() {
505	        var itemType = type.item();
506	        var kind = type.kind();
507	        if ( kind == FieldKind.FOREIGN_KEY )
508	            return null;
509	        else if ( kind == FieldKind.INTERMEDIATE_TABLE )
510	            return null;
511	        else if ( kind == FieldKind.PRIMITIVE) {
512	            if ( itemType == String.class )
513	                return "";
514	            else if ( itemType == Integer.class )
515	                return 0;
516	            else if ( itemType == Double.class )
517	                return 0.0;
518	            else if ( itemType == Boolean.class )
519	                return false;
520	            else if ( itemType == Long.class )
521	                return 0L;
522	            else if ( itemType == Float.class )
523	                return 0.0f;
524	            else if ( itemType == Short.class )
525	                return (short) 0;
526	            else if ( itemType == Byte.class )
527	                return (byte) 0;
528	            else if ( Enum.class.isAssignableFrom(itemType) )
529	                return itemType.getEnumConstants()[0];
530	            else
531	                throw new IllegalStateException( "Unknown property type: " + itemType);
532	        } else if ( kind == FieldKind.ID ) {
533	            return 1;
534	        } else
535	            throw new IllegalStateException("Unknown field kind: " + kind);
536	    }
537	
538	    public ProxyRef<Vals<Object>> asProperties( SQLiteDataBase db, long id, boolean eager ) {
539	        var wrapperType = type.wrapperType();
540	        if ( wrapperType == null )
541	            throw new IllegalStateException(
542	                    "Cannot create a property list proxy type for a field that does not have a wrapper type."
543	            );
544	        /*
545	            Now this is interesting.
546	            We have a list of properties represented in the form
547	            of an intermediate table.
548	            We know the name of the table, and we know the id of the
549	            model to which the table/model field belong.
550	            What we do not know is the ids of the models that are
551	            referenced by the intermediate table.
552	            So we need to query the table to find out.
553	        */
554	        IntermediateTable intermediateTable = getIntermediateTable().orElse(null);
555	        // We expect it to exist:
556	        if (intermediateTable == null)
557	            throw new IllegalStateException("The intermediate table does not exist");
558	
559	
560	        Vars<Object> vars = new ModelProperties(
561	                db, ownerModelClass, (FieldType.VarsOf) type, intermediateTable, id, eager
562	        );
563	
564	        // Let's create the proxy:
565	        return new ProxyRef<>((Vals<Object>) Proxy.newProxyInstance(
566	                        wrapperType.getClassLoader(),
567	                        new Class[]{wrapperType, Viewables.class},
568	                        (proxy, method, args) -> {
569	                            return _handleInvocation(proxy, method, args, vars, wrapperType);
570	                        }
571	                    ),
572	                    vars
573	                );
574	    }
575	
576	    @Override public String toString() {
577	        var itemType = type.item();
578	        var kind = type.kind();
579	        return "TableField[" + "baseName=" + name() + ", type=" + itemType + ", kind=" + kind + ']';
580	    }
581	
582	}
