        try (Statement stmt = _getConnection().createStatement()) {
            try (ResultSet rs = stmt.executeQuery(sql)) { // loop through the result set
                if ( start != null && !rs.isClosed() )
                    start.accept(rs);
                if ( each != null && !rs.isClosed() ) {
                    if ( start == null )
