plugins {
    id 'groovy'
    id 'java'
    id "com.github.node-gradle.node" version "7.1.0"
    // For static null checking:
    id "net.ltgt.errorprone" version "3.1.0"
}

group 'org.gleethos'
version '0.0.0'
sourceCompatibility = '21'

var REACT_SKIN_LOCATION = 'src/main/web-portal'

repositories {
    mavenCentral()
    maven { url 'https://jitpack.io' }
    google()
}

dependencies {

    // JSpecify
    errorprone "com.uber.nullaway:nullaway:0.12.8"
    compileOnly "com.google.code.findbugs:jsr305:3.0.2"
    errorprone "com.google.errorprone:error_prone_core:2.27.0"
    implementation group: 'com.google.errorprone', name: 'error_prone_annotations', version: '2.27.0'
    implementation 'org.jspecify:jspecify:1.0.0'


    implementation 'javax.websocket:javax.websocket-api:1.1'
    implementation 'org.eclipse.jetty:jetty-servlet:9.4.57.v20241219'
    implementation 'org.eclipse.jetty.websocket:websocket-server:9.4.57.v20241219'
    implementation 'org.eclipse.jetty:jetty-server:9.4.57.v20241219'

    implementation group: 'org.xerial', name: 'sqlite-jdbc', version: '3.50.3.0'
    implementation group: 'io.github.globaltcad', name: 'swing-tree', version:'0.23.1'

    // --- World engine GPU renderer (OpenGL backend behind the Renderer SPI) ---
    // LWJGL core + OpenGL, version-aligned via the BOM. Natives ship per OS/arch (the
    // packaging dimension of going GPU); add more 'runtimeOnly ...:natives-<platform>'
    // lines to support more targets. lwjgl3-awt provides the AWTGLCanvas; we exclude its
    // transitive LWJGL so our BOM-pinned 3.3.6 wins.
    implementation platform('org.lwjgl:lwjgl-bom:3.3.6')
    implementation 'org.lwjgl:lwjgl'
    implementation 'org.lwjgl:lwjgl-opengl'
    implementation 'org.lwjgl:lwjgl-jawt' // JAWT bindings the AWTGLCanvas needs (binds the JDK's own JAWT; no natives)
    runtimeOnly 'org.lwjgl:lwjgl::natives-linux'
    runtimeOnly 'org.lwjgl:lwjgl-opengl::natives-linux'
    runtimeOnly 'org.lwjgl:lwjgl::natives-windows'
    runtimeOnly 'org.lwjgl:lwjgl-opengl::natives-windows'
    runtimeOnly 'org.lwjgl:lwjgl::natives-macos'
    runtimeOnly 'org.lwjgl:lwjgl-opengl::natives-macos'
    runtimeOnly 'org.lwjgl:lwjgl::natives-macos-arm64'
    runtimeOnly 'org.lwjgl:lwjgl-opengl::natives-macos-arm64'
    implementation('org.lwjglx:lwjgl3-awt:0.2.3') { exclude group: 'org.lwjgl' }

    // Testing with Spock :
    testImplementation 'org.junit.jupiter:junit-jupiter-api:5.8.2'
    testRuntimeOnly 'org.junit.jupiter:junit-jupiter-engine:5.8.2'    // mandatory dependencies for using Spock

    testImplementation 'org.apache.groovy:groovy'
    testImplementation platform('org.spockframework:spock-bom:2.3-groovy-4.0')
    testImplementation 'org.spockframework:spock-core:2.3-groovy-4.0'
    testImplementation 'com.athaydes:spock-reports:2.5.1-groovy-4.0'

    implementation 'com.formdev:flatlaf-intellij-themes:3.6.1'
    implementation 'com.formdev:flatlaf:3.6.1' // Looks better than regular swing :)
    implementation group: 'com.metsci.ext.com.kitfox.svg', name: 'svg-salamander', version: '0.1.19'

    implementation group: 'org.json', name: 'json', version: '20250517'

    // Command line parsing :
    implementation 'org.jcommander:jcommander:2.0'

    // Logging :
    implementation group: 'org.slf4j', name: 'slf4j-api', version: '2.0.17'
    implementation group: 'org.slf4j', name: 'slf4j-simple', version: '2.0.17'

    // Integration test with Geb and Spock :
    testImplementation group: 'org.gebish', name: 'geb-spock', version: '7.0'
    testImplementation group: 'org.seleniumhq.selenium', name: 'selenium-firefox-driver', version: '4.34.0'

}

tasks.withType(JavaCompile).configureEach {
    // remove the if condition if you want to run NullAway on test code
    if (!name.toLowerCase().contains("test")) {
        options.errorprone {
            check("NullAway", net.ltgt.gradle.errorprone.CheckSeverity.ERROR)
            option("NullAway:AnnotatedPackages", "")
        }
    } else {
        options.errorprone {
            check("NullAway", net.ltgt.gradle.errorprone.CheckSeverity.WARN)
            option("NullAway:AnnotatedPackages", "")
        }
    }
}

// Read more about how to configure the plugin from
// https://github.com/srs/gradle-node-plugin/blob/master/docs/node.md
node {
    // Whether to download and install a specific Node.js version or not
    // If false, it will use the globally installed Node.js
    // If true, it will download node using above parameters
    // Note that npm is bundled with Node.js
    download = true

    // Version of node to download and install (only used if download is true)
    // It will be unpacked in the workDir
    version = "22.18.0"

    // Version of npm to use
    // If specified, installs it in the npmWorkDir
    // If empty, the plugin will use the npm command bundled with Node.js
    npmVersion = ""

    // Version of Yarn to use
    // Any Yarn task first installs Yarn in the yarnWorkDir
    // It uses the specified version if defined and the latest version otherwise (by default)
    yarnVersion = ""

    // Base URL for fetching node distributions
    // Only used if download is true
    // Change it if you want to use a mirror
    // Or set to null if you want to add the repository on your own.
    distBaseUrl = "https://nodejs.org/dist"

    // Specifies whether it is acceptable to communicate with the Node.js repository over an insecure HTTP connection.
    // Only used if download is true
    // Change it to true if you use a mirror that uses HTTP rather than HTTPS
    // Or set to null if you want to use Gradle's default behaviour.
    allowInsecureProtocol = null

    // The npm command executed by the npmInstall task
    // By default it is install but it can be changed to ci
    npmInstallCommand = "install"

    // The directory where Node.js is unpacked (when download is true)
    workDir = file("${project.projectDir}/.gradle/nodejs")

    // The directory where npm is installed (when a specific version is defined)
    npmWorkDir = file("${project.projectDir}/.gradle/npm")

    // The directory where yarn is installed (when a Yarn task is used)
    yarnWorkDir = file("${project.projectDir}/.gradle/yarn")

    // The Node.js project directory location
    // This is where the package.json file and node_modules directory are located
    // By default it is at the root of the current project
    nodeProjectDir = file("${project.projectDir}/$REACT_SKIN_LOCATION")

    // Whether the plugin automatically should add the proxy configuration to npm and yarn commands
    // according the proxy configuration defined for Gradle
    // Disable this option if you want to configure the proxy for npm or yarn on your own
    // (in the .npmrc file for instance)
    nodeProxySettings = ProxySettings.SMART
}

// Build the project locally
tasks.register('appNpmBuild', NpmTask) {
    description = "Builds production version of tribee-portal"
    workingDir = file("${project.projectDir}/$REACT_SKIN_LOCATION")
    args = ["run", "build"]
}

// Copies the project to the service folder
tasks.register('copyWebAppToWebRoot', Copy) {
    dependsOn appNpmBuild
    from "$REACT_SKIN_LOCATION/build"
    into 'src/main/resources/web/.'
}

/*
    Combines build and copy tasks!
    Use this for rebuilding the react frontend
    (rebuild the react app and copy the build folder to the resources folder)
*/
tasks.register('buildWebApp', NpmTask) {
    description = "Builds production version of tribee-portal"
    dependsOn appNpmBuild
    dependsOn copyWebAppToWebRoot
}

appNpmBuild.dependsOn npmInstall
compileJava.dependsOn copyWebAppToWebRoot
processResources.dependsOn copyWebAppToWebRoot

// A task which starts the 'Main' class of the project with a certain set of arguments
// Note that this is done in a new thread, so the task will finish immediately and we can run other tasks in parallel
tasks.register('runServer', JavaExec) {
    main = 'Main'
    classpath = sourceSets.main.runtimeClasspath
    args = ['--start-server', 'true', '--port', '8080', '--headless', 'true']
}

// Runs the world-engine demo. Choose the renderer backend with:
//   ./gradlew runWorldDemo                       (software Graphics2D, default)
//   ./gradlew runWorldDemo -Dengine.renderer=gl  (OpenGL backend)
tasks.register('runWorldDemo', JavaExec) {
    group = 'application'
    description = 'Runs the world-engine demo (use -Dengine.renderer=gl for the OpenGL backend).'
    mainClass = 'app.engine.world.demo.WorldEngineDemo'
    classpath = sourceSets.main.runtimeClasspath
    systemProperty 'engine.renderer', System.getProperty('engine.renderer', '')
}

// Runs the main() of any class, e.g. a standalone view demo:
//   ./gradlew runMain -PmainClass=app.campaign.CampaignView
tasks.register('runMain', JavaExec) {
    group = 'application'
    description = 'Runs the main() of the class given by -PmainClass=...'
    mainClass = providers.gradleProperty('mainClass').orElse('app.campaign.CampaignView')
    classpath = sourceSets.main.runtimeClasspath
}

// A task for executing the react tests:
tasks.register('appNpmTest', NpmTask) { // TODO: Make this depend on the server task!
    description = "Runs the react tests"
    workingDir = file("${project.projectDir}/$REACT_SKIN_LOCATION")
    args = ["run", "test"]
}

test {
    useJUnitPlatform()
    // Forward the opt-in flag for the heavyweight podman integration test into the forked test JVM.
    if ( System.getProperty('tribalism.podman.it') != null )
        systemProperty 'tribalism.podman.it', System.getProperty('tribalism.podman.it')
}

/* =====================================================================================
   Agent sandbox binaries (podman + git) — see VISION.md §9.5 / §9.8
   -------------------------------------------------------------------------------------
   The agent harness ships its OWN podman and git so it never depends on the host. Per the
   chosen strategy these are NOT committed: 'fetchSandboxBinaries' downloads pinned releases,
   verifies their SHA-256, and extracts them into a gitignored per-platform bundle dir that
   app.agent.sandbox.SandboxBinaries discovers at runtime. Currently Linux x86-64 only (§9.5).
   ===================================================================================== */
ext {
    sandboxPlatform = 'linux-x86_64'
    sandboxBundleDir = file("binaries/${sandboxPlatform}")
    sandboxCacheDir  = file('binaries/cache')

    // Single source of truth for the OS runtime dependency the native installers must declare. We ship
    // podman/crun/conmon/fuse-overlayfs ourselves, but the setuid-root newuidmap/newgidmap helpers
    // (rootless UID mapping) cannot be bundled and must come from the OS. See packaging/README.md and
    // app.agent.sandbox.PodmanSandboxRuntime. Keep in sync with packaging/linux/*.
    osRuntimeDependencies = [
        debian: ['uidmap'],          // provides newuidmap/newgidmap (Debian/Ubuntu)
        rpm   : ['shadow-utils'],    // base on Fedora/RHEL; declared for safety
        arch  : ['shadow'],
        alpine: ['shadow-uidmap'],
    ]

    // podman-static: a self-contained podman + crun/conmon/netavark/pasta/fuse-overlayfs bundle.
    podmanVersion = 'v5.8.2'
    podmanUrl     = "https://github.com/mgoltzsche/podman-static/releases/download/${podmanVersion}/podman-linux-amd64.tar.gz"
    podmanSha256  = '228b9adf1ba3585d1d72f0a4bb9a669de5ea806d13884b2c43b5e65601a1a580'

    // dugite-native: the portable git GitHub Desktop embeds (purpose-built for bundling).
    gitVersion = 'v2.53.0-3'
    gitUrl     = 'https://github.com/desktop/dugite-native/releases/download/v2.53.0-3/dugite-native-v2.53.0-f49d009-ubuntu-x64.tar.gz'
    gitSha256  = 'b3a85433c8dfde76d21b90938ad2f971653deff4340b1b4d347258c63250eafc'
}

// Downloads to dest (if absent/mismatched), following redirects, then verifies SHA-256.
def fetchVerified(String url, File dest, String expectedSha) {
    dest.parentFile.mkdirs()
    if ( dest.exists() && sha256Of(dest) == expectedSha ) {
        logger.lifecycle("sandbox: ${dest.name} present and verified")
        return
    }
    logger.lifecycle("sandbox: downloading ${url}")
    def current = url
    for ( int hop = 0; hop < 6; hop++ ) {
        def conn = new URL(current).openConnection()
        conn.setRequestProperty('User-Agent', 'tribalism-build')
        conn.instanceFollowRedirects = false
        conn.connectTimeout = 30_000
        conn.readTimeout = 120_000   // never hang forever on a stalled socket (the bug we hit once)
        conn.connect()
        int code = conn.responseCode
        if ( code in [301, 302, 303, 307, 308] ) { current = conn.getHeaderField('Location'); continue }
        if ( code != 200 ) throw new GradleException("download failed (${code}) for ${current}")
        dest.withOutputStream { out -> conn.inputStream.withStream { it.transferTo(out) } }
        break
    }
    def actual = sha256Of(dest)
    if ( actual != expectedSha )
        throw new GradleException("SHA-256 mismatch for ${dest.name}:\n  expected ${expectedSha}\n  actual   ${actual}")
    logger.lifecycle("sandbox: verified ${dest.name} (${actual})")
}

def sha256Of(File file) {
    def md = java.security.MessageDigest.getInstance('SHA-256')
    file.withInputStream { ins ->
        byte[] buf = new byte[1 << 16]; int n
        while ( (n = ins.read(buf)) > 0 ) md.update(buf, 0, n)
    }
    return md.digest().encodeHex().toString()
}

tasks.register('fetchSandboxBinaries') {
    group = 'sandbox'
    description = 'Downloads + SHA-256-verifies podman and git into the gitignored binaries/<platform> bundle.'
    outputs.dir sandboxBundleDir
    doLast {
        def podmanTar = new File(sandboxCacheDir, "podman-${podmanVersion}.tar.gz")
        def gitTar    = new File(sandboxCacheDir, "git-${gitVersion}.tar.gz")
        fetchVerified(podmanUrl, podmanTar, podmanSha256)
        fetchVerified(gitUrl,    gitTar,    gitSha256)

        // podman-static wraps everything in a 'podman-linux-amd64/' dir — strip that leading segment.
        def podmanOut = new File(sandboxBundleDir, 'podman')
        delete podmanOut
        copy {
            from tarTree(resources.gzip(podmanTar))
            into podmanOut
            includeEmptyDirs = false
            eachFile { fcd -> fcd.relativePath = new RelativePath(true, fcd.relativePath.segments[1..-1] as String[]) }
        }
        // dugite git extracts bin/ etc/ libexec/ ... at the top level — no stripping.
        def gitOut = new File(sandboxBundleDir, 'git')
        delete gitOut
        copy { from tarTree(resources.gzip(gitTar)); into gitOut; includeEmptyDirs = false }

        // Ensure the executables are runnable (tar modes can be lost depending on the extractor).
        ant.chmod(dir: new File(podmanOut, 'usr/local/bin'), perm: 'a+rx', includes: '*')
        ant.chmod(dir: new File(podmanOut, 'usr/local/lib/podman'), perm: 'a+rx', includes: '*')
        ant.chmod(dir: new File(gitOut, 'bin'), perm: 'a+rx', includes: '*')
        logger.lifecycle("sandbox: bundle ready at ${sandboxBundleDir}")
    }
}

tasks.register('cleanSandboxBinaries', Delete) {
    group = 'sandbox'
    description = 'Removes the downloaded sandbox binaries bundle (keeps the verified cache).'
    delete sandboxBundleDir
}

// Stages the bundle into the build output so a packaged distribution can ship it.
tasks.register('bundleSandboxBinaries', Copy) {
    group = 'sandbox'
    description = 'Copies the fetched sandbox binaries into build/sandbox-binaries for packaging.'
    dependsOn 'fetchSandboxBinaries'
    from sandboxBundleDir
    into layout.buildDirectory.dir("sandbox-binaries/${sandboxPlatform}")
}

