import java.lang.classfile.*;
import java.lang.classfile.instruction.*;
import java.lang.constant.*;
import java.util.List;

public class CFProbe {
    interface V<T> { T get(); default <B> V<B> zoom(java.util.function.Function<T,B> g){ return null; } }
    record Prod(String name, double price) {}
    interface M { V<Prod> state(); default V<String> name(){ return state().zoom(Prod::name); } }
    public static void main(String[] a) throws Exception {
        byte[] bytes = CFProbe.class.getResourceAsStream("CFProbe$M.class").readAllBytes();
        ClassModel cm = ClassFile.of().parse(bytes);
        for (MethodModel mm : cm.methods()) {
            if (!mm.methodName().stringValue().equals("name")) continue;
            System.out.println("method desc="+mm.methodType().stringValue());
            for (CodeElement e : mm.code().orElseThrow()) {
                if (e instanceof InvokeInstruction inv)
                    System.out.println("INVOKE "+inv.opcode()+" "+inv.owner().asSymbol().descriptorString()+" "+inv.name().stringValue()+" "+inv.typeSymbol().descriptorString());
                else if (e instanceof InvokeDynamicInstruction idc) {
                    var bm = idc.invokedynamic().bootstrap();
                    var args = bm.arguments();
                    var mhe = (MethodHandleEntry) args.get(1);
                    DirectMethodHandleDesc d = (DirectMethodHandleDesc) mhe.asSymbol();
                    System.out.println("INDY impl owner="+d.owner().descriptorString()+" name="+d.methodName()+" invType="+d.invocationType().descriptorString()+" pc="+d.invocationType().parameterCount());
                }
            }
        }
    }
}
