7	sealed interface FieldType {
8	    sealed interface VarOf {
9	        record Id(Class<? extends Var<?>> var, Class<?> item) implements FieldType, VarOf {}
10	        record Primitive(Class<? extends Var<?>> var, Class<?> item) implements FieldType, VarOf {}
11	        record Value(Class<? extends Var<?>> var, Class<? extends dal.api.Value> item) implements FieldType, VarOf {}
12	        record Tuple(Class<? extends Var<?>> var, Class<? extends dal.api.Value> item) implements FieldType, VarOf {}
13	        record Model(Class<? extends Var<?>> var, Class<? extends dal.api.Model<?>> item) implements FieldType, VarOf {}
14	
