16	        Class<?> item();
17	    }
18	    sealed interface VarsOf {
19	        record Primitive(Class<? extends Vars<?>> vars, Class<?> item) implements FieldType, VarsOf {}
20	        record Value(Class<? extends Vars<?>> vars, Class<? extends dal.api.Value> item) implements FieldType, VarsOf {}
21	        record Model(Class<? extends Vars<?>> vars, Class<? extends dal.api.Model<?>> item) implements FieldType, VarsOf {}
22	
23	        Class<?> vars();
24	        Class<?> item();
25	        default VarOf varOf() {
26	            return switch (this) {
27	                case Primitive ignored -> new VarOf.Primitive((Class) Var.class, item());
28	                case Value ignored -> new VarOf.Value((Class) Var.class, (Class) item());
29	                case Model ignored -> new VarOf.Model((Class) Var.class, (Class) item());
