1	package dal.impl;
2	
3	import dal.api.DataBaseEntity;
4	import dal.api.Model;
5	import dal.api.Value;
6	import org.jspecify.annotations.NullMarked;
7	import sprouts.Association;
8	import sprouts.Tuple;
9	
10	import java.lang.ref.WeakReference;
11	import java.util.*;
12	import java.util.stream.Collectors;
13	
14	@NullMarked
15	final class EntityRegistry
16	{
17	    private Association<String, EntityTable> entityTables = Association.betweenLinked(String.class, EntityTable.class);
18	
19	    private final Map<String, Map<Long, WeakReference<ModelProxy<?>>>> modelProxies = new LinkedHashMap<>();
20	
21	    public EntityRegistry() {}
22	
23	    public void addTables(List<Class<? extends DataBaseEntity>> modelInterfaces)
24	    {
25	        modelInterfaces = modelInterfaces
26	                              .stream()
27	                              .filter(m -> !entityTables.containsKey(BasicSQLiteDataBase._tableNameFromClass(m)) ) // Filter out already added interfaces
28	                              .collect(Collectors.toList());
29	
30	        Set<Class<? extends DataBaseEntity>> distinct = new HashSet<>();
31	        for (var modelTable : entityTables.values())
32	            modelTable.entityType().ifPresent(modelInterface -> distinct.add(modelInterface));
33	
34	        distinct.addAll(modelInterfaces);
35	        var finalModelInterfaces = (Tuple<Class<? extends DataBaseEntity>>) ((Tuple) Tuple.of(Class.class)).addAll(distinct);
36	
37	        Map<String, EntityTable> newModelTables = new LinkedHashMap<>();
38	        for (Class<? extends DataBaseEntity> modelInterface : finalModelInterfaces) {
39	            if ( Model.class.isAssignableFrom(modelInterface) ) {
40	                EntityTable modelTable = ModelTable.of((Class<? extends Model<?>>) modelInterface, finalModelInterfaces);
41	                Objects.requireNonNull(modelTable, "modelTable");
42	                newModelTables.put(modelTable.getTableName(), modelTable);
43	                modelTable.getFields().forEach(
44	                        f -> f.getIntermediateTable().ifPresent(
45	                                t -> newModelTables.put(t.getTableName(), t)
46	                        )
47	                );
48	            } else if (Value.class.isAssignableFrom(modelInterface)) {
49	                ValueTable valueTable = ValueTable.of((Class<? extends Value>) modelInterface, finalModelInterfaces);
50	                Objects.requireNonNull(valueTable, "valueTable");
51	                newModelTables.put(valueTable.getTableName(), valueTable);
52	                valueTable.getFields().forEach(
53	                        f -> f.getIntermediateTable().ifPresent(
54	                                t -> newModelTables.put(t.getTableName(), t)
55	                        )
56	                );
57	            }
58	        }
59	        /*
60	            Now we need to check if there are any circular references
61	            We do this by checking if there are any cycles in the graph of the model tables
62	         */
63	        for (EntityTable modelTable : newModelTables.values()) {
64	            Set<EntityTable> visited = new HashSet<>();
65	            Set<EntityTable> currentPath = new HashSet<>();
66	            if (_hasCycle(modelTable, visited, currentPath, newModelTables))
67	                throw new IllegalArgumentException(
68	                        "The model " + modelTable.getTableName() + " has a circular reference!"
69	                );
70	        }
71	
72	        /*
73	            Now we need to determine the order in which we create the tables
74	            We will do this by creating a map between all models as keys and their references
75	            as values.
76	            If they are referencing themselves we treat it as no reference.
77	            We will then fill a list with the models that have no references
78	            and then remove them from the map and repeat the process until the map is empty.
79	        */
80	        List<Class<?>> sortedModels = new ArrayList<>();
81	        Map<Class<?>, List<Class<?>>> modelReferences = new LinkedHashMap<>();
82	        List<EntityTable> intermediateTables = new ArrayList<>();
83	
84	        for (EntityTable modelTable : newModelTables.values()) {
85	            Tuple<Class<? extends DataBaseEntity>> referencedModels = modelTable.getReferencedModels();
86	            List<Class<?>> references = new ArrayList<>();
87	            for (Class<? extends DataBaseEntity> referencedModel : referencedModels) {
88	                if (!referencedModel.equals(modelTable.entityType().orElse(null))) {
89	                    references.add(referencedModel);
90	                }
91	            }
92	            modelTable.entityType().ifPresent(m -> modelReferences.put(m, references));
93	            // If it is not present then it is an intermediate table and we do not need to add it to the map
94	            // because it is not referenced by any other table, so it can be created at the end.
95	            if (modelTable instanceof IntermediateTable) {
96	                intermediateTables.add(modelTable);
97	            }
98	        }
99	
100	        while (!modelReferences.isEmpty()) {
101	            List<Class<?>> modelsWithoutReferences = new ArrayList<>();
102	            for (Map.Entry<Class<?>, List<Class<?>>> entry : modelReferences.entrySet()) {
103	                if (entry.getValue().isEmpty()) {
104	                    modelsWithoutReferences.add(entry.getKey());
105	                }
106	            }
107	            if (modelsWithoutReferences.isEmpty()) {
108	                throw new IllegalArgumentException(
109	                        "There are circular references in the model interfaces!"
110	                );
111	            }
112	            for (Class<?> modelWithoutReference : modelsWithoutReferences) {
113	                modelReferences.remove(modelWithoutReference);
114	                sortedModels.add(modelWithoutReference);
115	            }
116	            for (Map.Entry<Class<?>, List<Class<?>>> entry : modelReferences.entrySet()) {
117	                entry.getValue().removeAll(modelsWithoutReferences);
118	            }
119	        }
120	
121	        for (Class<?> model : sortedModels) {
122	            EntityTable modelTable = newModelTables.get(BasicSQLiteDataBase._tableNameFromClass(model));
123	            Objects.requireNonNull(modelTable, "No table found for model class '" + model + "'");
124	            entityTables = entityTables.put(modelTable.getTableName(), modelTable);
125	        }
126	
127	        // Now we need to add intermediate tables
128	        for (EntityTable modelTable : intermediateTables) {
129	            entityTables = entityTables.put(modelTable.getTableName(), modelTable);
130	        }
131	        // We are done!
132	    }
133	
134	    private boolean _hasCycle(
135	            EntityTable modelTable,
136	            Set<EntityTable> visited,
137	            Set<EntityTable> currentPath,
138	            Map<String, EntityTable> newModelTables
139	    ) {
140	        Objects.requireNonNull(modelTable, "modelTable");
141	        if (visited.contains(modelTable))
142	            return false;
143	        if (currentPath.contains(modelTable))
144	            return true;
145	        currentPath.add(modelTable);
146	        for (Class<? extends DataBaseEntity> referencedModel : modelTable.getReferencedModels()) {
147	            var tableName = BasicSQLiteDataBase._tableNameFromClass(referencedModel);
148	            var foundTable = newModelTables.get(tableName);
149	            if ( foundTable == null ) {
150	                throw new IllegalStateException(
151	                        "Internal error detected! Failed to find a table configuration for '" + referencedModel
152	                        + "' and table name '" + tableName + "'."
153	                    );
154	            }
155	            if (_hasCycle(foundTable, visited, currentPath, newModelTables))
156	                return true;
157	        }
158	        currentPath.remove(modelTable);
159	        visited.add(modelTable);
160	        return false;
161	    }
162	
163	    public Tuple<EntityTable> getTables() {
164	        return entityTables.values();
165	    }
166	
167	    public boolean hasTable(String tableName) {
168	        return entityTables.containsKey(tableName);
169	    }
170	
171	    public EntityTable getTable(String tableName) {
172	        return entityTables.get(tableName).orElseThrow();
173	    }
174	
175	    public boolean hasTable(Class<? extends Model<?>> modelInterface) {
176	        return entityTables.values().stream().anyMatch(t -> t.entityType().isPresent() && t.entityType().get().equals(modelInterface));
177	    }
178	
179	    Optional<ModelTable> getTable(Class<? extends Model<?>> modelInterface ) {
180	        String tableName = BasicSQLiteDataBase._tableNameFromClass(modelInterface);
181	        var found1 = entityTables.get(tableName).map(ModelTable.class::cast).orElse(null);
182	        var found2 = entityTables.values()
183	                                .stream()
184	                                .filter(t -> t.entityType().isPresent() && t.entityType().get().equals(modelInterface))
185	                                .findFirst()
186	                                .orElse(null);
187	
188	        // Let's do some consistency checks
189	        if ( found1 != found2 )
190	            throw new IllegalStateException("The model table for " + modelInterface + " is not consistent!");
191	
192	        return Optional.ofNullable(found1);
193	    }
194	
195	    Optional<ValueTable> getValueTable(Class<? extends Value> valueClass ) {
196	        String tableName = BasicSQLiteDataBase._tableNameFromClass(valueClass);
197	        var found1 = entityTables.get(tableName).map(ValueTable.class::cast).orElse(null);
198	        var found2 = entityTables.values()
199	                .stream()
200	                .filter(t -> t.entityType().isPresent() && t.entityType().get().equals(valueClass))
201	                .findFirst()
202	                .orElse(null);
203	
204	        // Let's do some consistency checks
205	        if ( found1 != found2 )
206	            throw new IllegalStateException("The value table for " + valueClass + " is not consistent!");
207	
208	        return Optional.ofNullable(found1);
209	    }
210	
211	    public Tuple<IntermediateTable> getIntermediateTables() {
212	        return entityTables.values().stream().filter(t -> t instanceof IntermediateTable).map(IntermediateTable.class::cast).collect(Tuple.collectorOf(IntermediateTable.class));
213	    }
214	
215	    public Tuple<IntermediateTable> getIntermediateTableInvolving(Class<? extends Model<?>> modelInterface) {
216	        return getIntermediateTables().stream().filter(t -> t.getReferencedModels().contains(modelInterface)).collect(Tuple.collectorOf(IntermediateTable.class));
217	    }
