/** Builds an {@code IN}/{@code NOT IN} operator fragment with the right number of {@code ?} placeholders. */
private static String _placeholders(String op, int count) {
    StringBuilder sb = new StringBuilder(op).append(" (");
    for ( int i = 0; i < count; i++ ) {
        sb.append("?");
        if ( i < count - 1 )
            sb.append(", ");
    }
    return sb.append(")").toString();
}

@Override
public void close() {
    _db.close();
}

private <T, M extends Model<M>> Selection _resolveSelection(
    Function<M, Val<T>> selector,
    Class<M> model
) {
    var propSelector = new PropertySelectionProxy(_getTableFor(model), _entityRegistry);
    // Driving the selector records the selection (or throws if it is not a valid one); the
    // returned stand-in property proxy is intentionally unused.
    var ignored = selector.apply((M) Proxy.newProxyInstance(
                            model.getClassLoader(),
                            new Class<?>[]{model},
                            propSelector
                        ));
    return propSelector.getSelection().orElseThrow();
}

/**
 *  Resolves a nested selector: a root model property selector (which must pick a single
 *  Value-typed field) plus one or more navigation functions into that value. The navigation is
 *  resolved by {@link NestedSelectionResolver} (probe-execution), then rendered as a zoom path.
 */
private <M extends Model<M>, V> Selection _nested(
    Class<M> model,
    Function<M, Val<V>> rootSelector,
    List<Function<Object, Object>> lenses
) {
    Selection rootSel = _resolveSelection(rootSelector, model);
    if ( !(rootSel instanceof Selection.Flat flat) )
        throw new IllegalArgumentException(
            "The root selector of a nested where(..)/and(..)/or(..) must select a single Value-typed " +
            "model property (e.g. AccountModel::user), not a derived/zoom property."
        );
    String what = model.getSimpleName() + "::" + flat.field().baseName();
    return NestedSelectionResolver.resolve(flat.field(), lenses, _entityRegistry, what);
}

@SuppressWarnings("unchecked")
private static List<Function<Object, Object>> _lenses(Function<?, ?>... fns) {
    List<Function<Object, Object>> out = new ArrayList<>(fns.length);
    for ( Function<?, ?> f : fns )
        out.add((Function<Object, Object>) f);
    return out;
}

public Map<String, List<String>> query(String sql) {
    Map<String, List<Object>> result = _db._query(sql, Collections.emptyList());
    return result.entrySet().stream()
            .collect(Collectors.toMap(
                    Map.Entry::getKey,
                    e -> e.getValue().stream()
                            .map(Object::toString)
                            .toList()
                ));
}

long _storeValueAndIncreaseCounter(Value databaseValue) {
    var valueTable = _entityRegistry.getValueTable(databaseValue.getClass())
            .orElseThrow(() -> new IllegalArgumentException(
                    "The value table for " + databaseValue.getClass().getName() + " does not exist!")
            );
    int hashCode = databaseValue.hashCode();
    var existingId = _findIdOfValue(valueTable, databaseValue, hashCode);
    if ( existingId < 0 ) {
        // We need to create a new entry in the value table
        Tuple<Object> rowOfValues = _convertValueToRowOfValues(valueTable, databaseValue, hashCode);
        existingId = _storeEntity(valueTable, databaseValue.getClass(),rowOfValues);
        // Populate intermediate tables for any tuple-typed components of the record:
        _populateIntermediateTablesForValue(valueTable, databaseValue, existingId);
    }
    _modifyUsageCounter(valueTable, existingId, +1);
    return existingId;
}

private void _populateIntermediateTablesForValue(
    ValueTable valueTable,
    Value value,
    long valueId
) {
    for (EntityTableField field : valueTable.getFields()) {
        if (!field.requiresIntermediateTable()) continue;
        try {
            Method method = value.getClass().getMethod(field.baseName());
            Object fieldValue = method.invoke(value);
            if (fieldValue == null) continue;
            if (!(fieldValue instanceof Tuple))
                throw new IllegalStateException(
                        "Expected a Tuple for intermediate-table field '" + field.baseName() +
                        "' on value '" + value.getClass().getName() + "', but got " + fieldValue.getClass().getName()
                );
            @SuppressWarnings("unchecked")
            Class<? extends Value> itemType = (Class<? extends Value>) field.type().item();
            Tuple<?> tuple = (Tuple<?>) fieldValue;
            int pos = 0;
            for (Object item : tuple) {
                if (item != null) {
                    long childId = _storeValueAndIncreaseCounter((Value) item);
                    _insertIntermediateTableRow(
                            valueTable.getTableName(), field.baseName(), valueId, itemType, childId, pos
                    );
                }
                pos++;
            }
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException(e);
        }
    }
}

long _removeValueAndDecrementCounter(Value databaseValue) {
    var valueTable = _entityRegistry.getValueTable(databaseValue.getClass())
                                        .orElseThrow(() -> new IllegalArgumentException(
                                            "The value table for " + databaseValue.getClass().getName() + " " +
                                            "does not exist!"
                                        ));
    int hashCode = databaseValue.hashCode();
    var existingId = _findIdOfValue(valueTable, databaseValue, hashCode);
    if ( existingId >= 0 ) {
        String sql = "SELECT "+ValueTable.USAGE_FIELD_COUNTER+" FROM " + valueTable.getTableName() +
                     " WHERE "+ModelTable.ID+" = ?";
        Map<String, List<Object>> result = _db._query(sql, Collections.singletonList(existingId));
        if ( result.isEmpty() )
            return -1; // Not found
        if ( result.values().stream().anyMatch( v -> v.size() != 1 ) )
            throw new IllegalStateException();
        var usages = ((Number) result.get(ValueTable.USAGE_FIELD_COUNTER).get(0)).intValue();
        if ( usages == 1 ) {
            // Last reference: recursively decrement nested values, then delete this row.
            _decrementNestedValuesOf(databaseValue, valueTable, existingId);
            _delete(valueTable.getTableName(), Collections.singletonList(existingId));
        } else {
            // Reduce usage counter
            _modifyUsageCounter(valueTable, existingId, -1);
        }
    }
    return existingId;
}

/**
 *  When a value row is about to be deleted (its usage counter has reached zero),
 *  any nested value references it owns must also be released. This walks the
 *  record components of the value: for {@link Value} components it decrements
 *  the referenced row, and for {@link Tuple} components it clears the
 *  intermediate table and decrements every contained value.
 */
private void _decrementNestedValuesOf(Value value, ValueTable valueTable, long valueId) {
