        elif isinstance(v,dict): print(f"{k}: {{{len(v)} keys}}")
    # try to find redaction categories
    for key in ('redactions','replacements','findings','counts','summary'):
        if key in r:
            v=r[key]
            if isinstance(v,list):
                c=collections.Counter(x.get('type') or x.get('category') or x.get('kind') for x in v if isinstance(x,dict))
                print("  ",key,"by type:",dict(c))
            elif isinstance(v,dict):
                print("  ",key,":",v)
else:
